1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioResult = {
6	  results: QuoteResult[];
7	};
8	
9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	} as const satisfies Record<string, number>;
17	
18	type InsurableItemType = keyof typeof BASE_PREMIUMS;
19	
20	type Item = {
21	  type: InsurableItemType;
22	  material?: string;
23	  enchantment?: number;
24	  cursed?: boolean;
25	};
26	
27	type QuoteStep = {
28	  op: "quote";
29	  items: Item[];
30	};
31	
32	type Customer = {
33	  yearsWithMHPCO: number;
34	};
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: QuoteStep[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
43	const CURSE_SURCHARGE_PERCENT = 50;
44	
45	const percentOf = (amount: number, percent: number): number =>
46	  (amount * percent) / 100;
47	
48	// The MHPCO always rounds in its own favour: premiums (which the customer
49	// pays) go up. Payouts round down, but no test demands that yet.
50	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
51	
52	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
53	
54	// Exactly this many components of the same type form a "building block",
55	// priced as a unit rather than per item.
56	const BUILDING_BLOCK_SIZE = 3;
57	const BUILDING_BLOCK_BASE_PREMIUM = 60;
58	
59	const sumOf = (amounts: number[]): number =>
60	  amounts.reduce((total, amount) => total + amount, 0);
61	
62	const alikeItemGroups = (items: Item[]): Item[][] => {
63	  const groupsByType = new Map<InsurableItemType, Item[]>();
64	
65	  for (const item of items) {
66	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
67	  }
68	
69	  return [...groupsByType.values()];
70	};
71	
72	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
73	  alikeItems.length === BUILDING_BLOCK_SIZE;
74	
75	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
76	  formsBuildingBlock(alikeItems)
77	    ? BUILDING_BLOCK_BASE_PREMIUM
78	    : sumOf(alikeItems.map(itemBasePremiumOf));
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
82	
83	// Item-specific modifiers apply to the base premium of the affected item.
84	const itemModifiersOf = (item: Item): number =>
85	  item.cursed ? percentOf(itemBasePremiumOf(item), CURSE_SURCHARGE_PERCENT) : 0;
86	
87	const quote = (step: QuoteStep): QuoteResult => {
88	  const basePremium = policyBasePremiumOf(step.items);
89	  const itemModifiers = sumOf(step.items.map(itemModifiersOf));
90	  const initialAssessmentSurcharge = percentOf(
91	    basePremium,
92	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
93	  );
94	
95	  return {
96	    premium: roundedUpInMHPCOsFavour(
97	      basePremium + itemModifiers + initialAssessmentSurcharge + PROCESSING_FEE,
98	    ),
99	  };
100	};
101	
102	export const runScenario = (scenario: Scenario): ScenarioResult => {
103	  return { results: scenario.steps.map(quote) };
104	};
